17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.ArrayList;
25	import java.util.Collection;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit logger; each successful owner create emits one line here. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        applyGoldTier(ownerDto, owner);
110	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
111	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = normalizeAddress(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        if (owner.getEmail() != null) {
129	            String email = normalizeEmail(owner.getEmail());
130	            if (email == null) {
131	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	            }
133	            owner.setEmail(email);
134	        }
135	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
136	        if (effectiveRegistrationDate == null) {
137	            effectiveRegistrationDate = LocalDate.now();
138	        }
139	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
142	            return new ResponseEntity<>(HttpStatus.CONFLICT);
143	        }
144	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        for (Owner existing : this.clinicService.findAllOwners()) {
148	            if (telephone.equals(toE164(existing.getTelephone()))) {
149	                return new ResponseEntity<>(HttpStatus.CONFLICT);
150	            }
151	        }
152	        String lastNameKey = householdKey(owner.getLastName());
153	        String addressKey = householdKey(owner.getAddress());
154	        List<Owner> householdMembers = new ArrayList<>();
155	        for (Owner existing : this.clinicService.findAllOwners()) {
156	            if (lastNameKey.equals(householdKey(existing.getLastName()))
157	                && addressKey.equals(householdKey(existing.getAddress()))) {
158	                householdMembers.add(existing);
159	            }
160	        }
161	        if (!householdMembers.isEmpty()) {
162	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
163	                return new ResponseEntity<>(HttpStatus.CONFLICT);
164	            }
165	            String householdId = householdId(lastNameKey, addressKey);
166	            owner.setHouseholdId(householdId);
167	            for (Owner member : householdMembers) {
168	                if (!householdId.equals(member.getHouseholdId())) {
169	                    member.setHouseholdId(householdId);
170	                    this.clinicService.saveOwner(member);
171	                }
172	            }
173	        }
174	        owner.setTelephone(telephone);
175	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
176	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
177	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
178	        this.clinicService.saveOwner(owner);
179	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        applyGoldTier(ownerDto, owner);
183	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        currentOwner.setAddress(ownerFieldsDto.getAddress());
197	        currentOwner.setCity(ownerFieldsDto.getCity());
198	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
199	        currentOwner.setLastName(ownerFieldsDto.getLastName());
200	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
201	        this.clinicService.saveOwner(currentOwner);
202	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Transactional
207	    @Override
208	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        this.clinicService.deleteOwner(owner);
214	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        HttpHeaders headers = new HttpHeaders();
225	        Pet pet = petMapper.toPet(petFieldsDto);
226	        owner.setId(ownerId);
227	        pet.setOwner(owner);
228	        pet.getType().setName(null);
229	        this.clinicService.savePet(pet);
230	        PetDto petDto = petMapper.toPetDto(pet);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
232	            .buildAndExpand(pet.getId()).toUri());
233	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
239	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
240	        if (currentOwner != null) {
241	            Pet currentPet = this.clinicService.findPetById(petId);
242	            if (currentPet != null) {
243	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
244	                currentPet.setName(petFieldsDto.getName());
245	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
246	                this.clinicService.savePet(currentPet);
247	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
256	        HttpHeaders headers = new HttpHeaders();
257	        Visit visit = visitMapper.toVisit(visitFieldsDto);
258	        Pet pet = new Pet();
259	        pet.setId(petId);
260	        visit.setPet(pet);
261	        this.clinicService.saveVisit(visit);
262	        VisitDto visitDto = visitMapper.toVisitDto(visit);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
264	            .buildAndExpand(visit.getId()).toUri());
265	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
266	    }
267	
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner != null) {
274	            Pet pet = owner.getPet(petId);
275	            if (pet != null) {
276	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
277	            }
278	        }
279	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	    }
281	
282	    /**
283	     * The maximum number of owners permitted per city. Owner creation is rejected once the
284	     * owner's city already contains this many owners.
285	     */
286	    private static final int MAX_OWNERS_PER_CITY = 50;
287	
288	    /**
289	     * Counts how many existing owners live in the given city, compared case-insensitively.
290	     * This is evaluated before the new owner is persisted, so the owner being created is not
291	     * included in the count.
292	     *
293	     * @param city the new owner's city
294	     * @return the number of existing owners in that city
295	     */
296	    private int countOwnersInCity(String city) {
297	        int count = 0;
298	        for (Owner existing : this.clinicService.findAllOwners()) {
299	            if (city.equalsIgnoreCase(existing.getCity())) {
300	                count++;
301	            }
302	        }
303	        return count;
304	    }
305	
306	    /**
307	     * The maximum number of owners that may be created in a single business day. Owner
308	     * creation is rejected once this many owners already fall on the new owner's adjusted
309	     * business day {@code registrationDate}.
310	     */
311	    private static final int MAX_OWNERS_PER_DAY = 100;
312	
313	    /**
314	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
315	     * to the following Monday, while a weekday is returned unchanged.
316	     *
317	     * @param date the date to adjust
318	     * @return the same date if it is a weekday, otherwise the following Monday
319	     */
320	    private LocalDate toBusinessDay(LocalDate date) {
321	        DayOfWeek dayOfWeek = date.getDayOfWeek();
322	        if (dayOfWeek == DayOfWeek.SATURDAY) {
323	            return date.plusDays(2);
324	        }
325	        if (dayOfWeek == DayOfWeek.SUNDAY) {
326	            return date.plusDays(1);
327	        }
328	        return date;
329	    }
330	
331	    /**
332	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
333	     * registrationDate} rolls forward to the same business day. This is evaluated before the
334	     * new owner is persisted, so the owner being created is not included in the count.
335	     *
336	     * @param businessDay the adjusted business day to count against
337	     * @return the number of existing owners registered on that business day
338	     */
339	    private int countOwnersRegisteredOn(LocalDate businessDay) {
340	        int count = 0;
341	        for (Owner existing : this.clinicService.findAllOwners()) {
342	            LocalDate existingDate = existing.getRegistrationDate();
343	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
344	                count++;
345	            }
346	        }
347	        return count;
348	    }
349	
350	    /**
351	     * The number of owners that may be created on a single business day before a bulk-signup
352	     * warning is raised. Once more than this many owners already fall on the current business
353	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
354	     */
355	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
356	
357	    /**
358	     * Reports whether an unusually high number of owners have been created for today's business
359	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
360	     * the business day that {@code LocalDate.now()} rolls forward to.
361	     *
362	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
363	     */
364	    private boolean isBulkSignupDay() {
365	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
366	    }
367	
368	    /**
369	     * Builds the customer code for a newly created owner, formatted
370	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
371	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
372	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
373	     * to one more than the number of owners already in that city.
374	     *
375	     * @param city     the owner's city
376	     * @param lastName the owner's last name
377	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
378	     */
379	    private String nextCustomerCode(String city, String lastName) {
380	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
381	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
382	        int sequence = 1;
383	        for (Owner existing : this.clinicService.findAllOwners()) {
384	            if (city.equalsIgnoreCase(existing.getCity())) {
385	                sequence++;
386	            }
387	        }
388	        return String.format("%s-%s-%04d", city3, last3, sequence);
389	    }
390	
391	    /**
392	     * Builds the membership number for a newly created owner, formatted
393	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
394	     * customer code and {@code YY} is the last two digits of the owner's registration
395	     * date year, zero-padded to two digits.
396	     *
397	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
398	     * @param registrationDate the owner's registration date
399	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
400	     */
401	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
402	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
403	    }
404	
405	    /**
406	     * Counts how many existing owners share the given first and last name, compared
407	     * case-insensitively. This is evaluated before the new owner is persisted, so the
408	     * owner being created is not included in the count.
409	     *
410	     * @param firstName the new owner's first name
411	     * @param lastName  the new owner's last name
412	     * @return the number of existing owners with the same first and last name
413	     */
414	    private int countNamesakes(String firstName, String lastName) {
415	        int count = 0;
416	        for (Owner existing : this.clinicService.findAllOwners()) {
417	            if (firstName.equalsIgnoreCase(existing.getFirstName())
418	                && lastName.equalsIgnoreCase(existing.getLastName())) {
419	                count++;
420	            }
421	        }
422	        return count;
423	    }
424	
425	    /**
426	     * The number of owners that must share a household before its members are promoted to the
427	     * {@code GOLD} membership tier. Once an owner's household (owners sharing the same {@code
428	     * householdId}) reaches this many members, that owner is reported as {@code GOLD}.
429	     */
430	    private static final int HOUSEHOLD_GOLD_THRESHOLD = 3;
431	
432	    /**
433	     * Promotes the owner's membership tier to {@code GOLD} when the owner's household — the set of
434	     * owners sharing the same non-null {@code householdId} — has {@link #HOUSEHOLD_GOLD_THRESHOLD}
435	     * or more members. Otherwise the tier assigned by the mapper (the existing {@code SILVER} and
436	     * {@code BRONZE} rules) is left unchanged.
437	     *
438	     * @param ownerDto the mapped owner response whose tier may be promoted
439	     * @param owner    the owner entity supplying the {@code householdId}
440	     */
441	    private void applyGoldTier(OwnerDto ownerDto, Owner owner) {
442	        String householdId = owner.getHouseholdId();
443	        if (householdId == null) {
444	            return;
445	        }
446	        int members = 0;
447	        for (Owner existing : this.clinicService.findAllOwners()) {
448	            if (householdId.equals(existing.getHouseholdId())) {
449	                members++;
450	            }
451	        }
452	        if (members >= HOUSEHOLD_GOLD_THRESHOLD) {
453	            ownerDto.setMembershipTier(OwnerDto.MembershipTierEnum.GOLD);
454	        }
455	    }
456	
457	    /**
458	     * Canonical expansions applied to common street-type abbreviations during address
459	     * normalization. Keys and values are upper-cased so the lookup runs after the address
460	     * has itself been upper-cased.
461	     */
462	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
463	        "ST", "STREET",
464	        "RD", "ROAD",
465	        "AVE", "AVENUE");
466	
467	    /**
468	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
469	     * every run of internal whitespace is collapsed to a single space, the result is
470	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
471	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
472	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
473	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
474	     * returned and compared for household duplicates; an address that is blank once
475	     * normalized fails the required-field check.
476	     *
477	     * @param address the raw address value supplied by the client
478	     * @return the normalized address (empty string when {@code address} is null or blank)
479	     */
480	    private static String normalizeAddress(String address) {
481	        if (address == null) {
482	            return "";
483	        }
484	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
485	        if (collapsed.isEmpty()) {
486	            return "";
487	        }
488	        StringBuilder normalized = new StringBuilder(collapsed.length());
489	        for (String token : collapsed.split(" ")) {
490	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
491	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
492	            if (normalized.length() > 0) {
493	                normalized.append(' ');
494	            }
495	            normalized.append(expanded != null ? expanded : token);
496	        }
497	        return normalized.toString();
498	    }
499	
500	    /**
501	     * Normalizes a last name or address for household-duplicate comparison: leading and
502	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
503	     * single space and the result is lower-cased. Two owners are considered to share a
504	     * household when both their last names and addresses produce the same key.
505	     *
506	     * @param value the raw last name or address value
507	     * @return the normalized comparison key (empty string when {@code value} is null)
508	     */
509	    private static String householdKey(String value) {
510	        if (value == null) {
511	            return "";
512	        }
513	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
514	    }
515	
516	    /**
517	     * Derives the stable shared household identifier for the given normalized last name
518	     * and address keys. The identifier is deterministic — the same household (same
519	     * {@link #householdKey normalized} last name and address) always maps to the same
520	     * value — so every owner who joins a household is assigned an identical id. It is the
521	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
522	     * '<lastNameKey>|<addressKey>'}.
523	     *
524	     * @param lastNameKey the normalized last name key
525	     * @param addressKey  the normalized address key
526	     * @return the shared household identifier
527	     */
528	    private static String householdId(String lastNameKey, String addressKey) {
529	        String source = lastNameKey + "|" + addressKey;
530	        try {
531	            byte[] digest = MessageDigest.getInstance("SHA-256")
532	                .digest(source.getBytes(StandardCharsets.UTF_8));
533	            StringBuilder hex = new StringBuilder(digest.length * 2);
534	            for (byte b : digest) {
535	                hex.append(String.format("%02x", b));
536	            }
537	            return hex.substring(0, 12).toUpperCase();
538	        } catch (NoSuchAlgorithmException e) {
539	            throw new IllegalStateException("SHA-256 not available", e);
540	        }
541	    }
542	
543	    /**
544	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
545	     * and brackets are stripped. When the number already carries a leading {@code '+'}
546	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
547	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
548	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
549	     *
550	     * @param telephone the raw telephone value supplied by the client
551	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
552	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
553	     */
554	    private static String toE164(String telephone) {
555	        if (telephone == null) {
556	            return null;
557	        }
558	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
559	        String digits;
560	        if (cleaned.startsWith("+")) {
561	            digits = cleaned.substring(1);
562	        } else {
563	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
564	            digits = "61" + national;
565	        }
566	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
567	    }
568	
569	    /**
570	     * Normalizes an owner email for creation. A present email must be a syntactically
571	     * valid address; the returned value is lower-cased.
572	     *
573	     * @param email the raw email value supplied by the client (never {@code null} here)
574	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
575	     *         address (signalling a 400 Bad Request)
576	     */
577	    private static String normalizeEmail(String email) {
578	        String trimmed = email.trim();
579	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
580	            return null;
581	        }
582	        return trimmed.toLowerCase();
583	    }
584	}
